import{_ as s,C as E,o,c,a2 as a,b as d,w as e,a as i,E as l,a3 as n}from"./chunks/framework.RycU2wFZ.js";const m=JSON.parse('{"title":"AgentPay 配置发布与运行时缓存契约规范 (T1.4 Specification)","description":"","frontmatter":{},"headers":[],"relativePath":"specs/config-publishing.md","filePath":"specs/config-publishing.md","lastUpdated":1792396280000}'),A={name:"specs/config-publishing.md"};function g(h,t,u,_,B,p){const r=E("Mermaid");return o(),c("div",null,[t[2]||(t[2]=a('<h1 id="agentpay-配置发布与运行时缓存契约规范-t1-4-specification" tabindex="-1">AgentPay 配置发布与运行时缓存契约规范 (T1.4 Specification) <a class="header-anchor" href="#agentpay-配置发布与运行时缓存契约规范-t1-4-specification" aria-label="Permalink to &quot;AgentPay 配置发布与运行时缓存契约规范 (T1.4 Specification)&quot;">​</a></h1><blockquote><p><strong>版本</strong>：v2.0.0 (T1.4 统一规范)<br><strong>状态</strong>：<strong>已定稿 (Approved Specification)</strong><br><strong>适用范围</strong>：Web 管理控制台（控制面）、Go Gateway（数据面）、PostgreSQL 配置持久化<br><strong>机器可读模式</strong>：</p><ul><li><a href="https://github.com/open-agentpay/AgentPay/blob/main/specs/conformance/config-snapshot.schema.json" target="_blank" rel="noreferrer"><code>specs/conformance/config-snapshot.schema.json</code></a> (不可变快照 JSON Schema)</li><li><a href="https://github.com/open-agentpay/AgentPay/blob/main/specs/test-vectors/config-publishing.json" target="_blank" rel="noreferrer"><code>specs/test-vectors/config-publishing.json</code></a> (配置发布与回滚测试向量)</li></ul></blockquote><hr><h2 id="_1-核心设计原则" tabindex="-1">1. 核心设计原则 <a class="header-anchor" href="#_1-核心设计原则" aria-label="Permalink to &quot;1. 核心设计原则&quot;">​</a></h2><ol><li><strong>草稿绝对隔离（Draft Isolation）</strong>： <ul><li>处于草稿态（<code>draft</code>）的路由或策略变更仅存在于管理控制台会话或草稿区，<strong>严禁对在线 Gateway 请求产生任何实质影响</strong>。</li></ul></li><li><strong>不可变版本快照（Immutable Snapshot &amp; Content Addressing）</strong>： <ul><li>配置发布一旦完成，系统立刻生成一份完整的全局配置快照（包含该租户名下所有的 Routes、Policies 及绑定关系），赋予递增的 <code>version_number</code> 与确定性 SHA-256 内容指纹（<code>snapshotHash</code>），存入 <code>ap_config_version</code>；</li><li>该快照<strong>绝对只读、严禁更新或删除</strong>。</li></ul></li><li><strong>数据面微秒级原子热切换（Zero-Downtime RCU Swap）</strong>： <ul><li>Go Gateway 在内存中采用类似 Linux RCU（Read-Copy-Update）的原子指针替换机制。当新版本发布生效时，Gateway 瞬间将活跃配置指针切换到新快照，正在执行中的旧请求继续引用旧快照直至完成，新请求即刻使用新规则，全程零连接中断、零吞吐抖动。</li></ul></li><li><strong>强健降级与高可用防御（Fail-Safe Degradation）</strong>： <ul><li>若控制面服务宕机、数据库短时失联或网络分区，Gateway <strong>坚决不停摆</strong>，严格基于内存与本地磁盘落盘镜像（Local Cache）持续提供代理与验签服务。</li></ul></li></ol><hr><h2 id="_2-配置生命周期状态机" tabindex="-1">2. 配置生命周期状态机 <a class="header-anchor" href="#_2-配置生命周期状态机" aria-label="Permalink to &quot;2. 配置生命周期状态机&quot;">​</a></h2>',7)),(o(),d(n,null,{default:e(()=>[l(r,{id:"mermaid-84",class:"mermaid",graph:"stateDiagram-v2%0A%20%20%20%20%5B*%5D%20--%3E%20Draft%20%3A%20%E7%AE%A1%E7%90%86%E5%91%98%E7%BC%96%E8%BE%91%E5%88%9B%E5%BB%BA%0A%20%20%20%20Draft%20--%3E%20Validated%20%3A%20%E8%A7%A6%E5%8F%91%E9%9D%99%E6%80%81%E7%BB%84%E5%90%88%E6%A0%A1%E9%AA%8C%0A%20%20%20%20Draft%20--%3E%20Rejected%20%3A%20%E6%A0%A1%E9%AA%8C%E5%8F%91%E7%8E%B0%E6%A0%BC%E5%BC%8F%2F%E9%80%BB%E8%BE%91%E7%9F%9B%E7%9B%BE%0A%20%20%20%20Rejected%20--%3E%20Draft%20%3A%20%E9%87%8D%E6%96%B0%E4%BF%AE%E6%94%B9%0A%20%20%20%20Validated%20--%3E%20Active%20%3A%20%E5%8F%91%E5%B8%83%E7%94%9F%E6%95%88%20(%E7%94%9F%E6%88%90%E4%B8%8D%E5%8F%AF%E5%8F%98%E5%BF%AB%E7%85%A7)%0A%20%20%20%20Active%20--%3E%20Superseded%20%3A%20%E5%8F%91%E5%B8%83%E6%9B%B4%E9%AB%98%E7%89%88%E6%9C%AC%20(%E8%87%AA%E5%A2%9E%E8%A6%86%E7%9B%96)%0A%20%20%20%20Active%20--%3E%20RolledBack%20%3A%20%E6%89%A7%E8%A1%8C%E4%B8%80%E9%94%AE%E5%9B%9E%E6%BB%9A%0A%20%20%20%20RolledBack%20--%3E%20Active%20%3A%20%E5%9B%9E%E6%BB%9A%E7%94%9F%E6%88%90%E6%96%B0%E7%89%88%E6%9C%AC%E6%BF%80%E6%B4%BB%0A"})]),fallback:e(()=>[...t[0]||(t[0]=[i(" Loading... ",-1)])]),_:1})),t[3]||(t[3]=a('<table tabindex="0"><thead><tr><th>状态 (State)</th><th>作用空间</th><th>对数据面 (Gateway) 的可见性</th><th>读写权限</th></tr></thead><tbody><tr><td><code>draft</code></td><td>控制台草稿区</td><td><strong>不可见</strong>（绝不加载）</td><td>可读写编辑</td></tr><tr><td><code>validated</code></td><td>控制台校验区</td><td><strong>不可见</strong></td><td>准备发布</td></tr><tr><td><code>active</code></td><td>生产线上运行态</td><td><strong>当前唯一生效版本</strong></td><td>只读不可变</td></tr><tr><td><code>superseded</code></td><td>历史归档区</td><td>仅用于已发出请求追溯关联</td><td>只读不可变</td></tr><tr><td><code>rolled_back</code></td><td>历史回滚区</td><td>仅用于审计与记录</td><td>只读不可变</td></tr></tbody></table><hr><h2 id="_3-严格静态校验矩阵-validation-rules" tabindex="-1">3. 严格静态校验矩阵 (Validation Rules) <a class="header-anchor" href="#_3-严格静态校验矩阵-validation-rules" aria-label="Permalink to &quot;3. 严格静态校验矩阵 (Validation Rules)&quot;">​</a></h2><p>在点击“发布”前，控制面必须通过下列<strong>无死角静态规则拦截</strong>，任何一条失败均禁止发布：</p><h3 id="_3-1-路由层校验-route-rules" tabindex="-1">3.1 路由层校验 (Route Rules) <a class="header-anchor" href="#_3-1-路由层校验-route-rules" aria-label="Permalink to &quot;3.1 路由层校验 (Route Rules)&quot;">​</a></h3><ol><li><strong>URI 格式合规</strong>：<code>upstream_url</code> 必须是合法 URI（以 <code>http://</code> 或 <code>https://</code> 开头），禁止私有非法协议；</li><li><strong>PathPattern 唯一性</strong>：同一租户内 <code>path_pattern</code> 绝对唯一，禁止模糊重叠歧义匹配；</li><li><strong>收款地址校验</strong>：<code>payee_address</code> 必须符合有效以太坊地址规范（<code>^0x[a-fA-F0-9]{40}$</code>）；</li><li><strong>定价非负</strong>：<code>price_base_units &gt;= 0</code>（支持免费或付费路由）；</li><li><strong>支付方式枚举</strong>：<code>allowed_payment_methods</code> 严格限定于 <code>wallet</code>、<code>onchain</code>、<code>both</code> 之一。</li></ol><h3 id="_3-2-策略层校验-policy-rules" tabindex="-1">3.2 策略层校验 (Policy Rules) <a class="header-anchor" href="#_3-2-策略层校验-policy-rules" aria-label="Permalink to &quot;3.2 策略层校验 (Policy Rules)&quot;">​</a></h3><ol><li><strong>预算上限阶梯校验</strong>：单笔上限必须严格小于或等于 24 小时滚动预算上限： $$\\text{max_amount_per_request} \\le \\text{rolling_24h_budget_cap}$$</li><li><strong>网络白名单校验</strong>：<code>whitelisted_networks</code> 每一项必须符合 CAIP-2 规范（如 <code>eip155:42161</code>）；</li><li><strong>熔断阈值合理性</strong>：<code>circuit_breaker_max_rpm &gt;= 1</code>，避免非法零频次导致默认直接熔断。</li></ol><hr><h2 id="_4-不可变快照生成与哈希指纹算法" tabindex="-1">4. 不可变快照生成与哈希指纹算法 <a class="header-anchor" href="#_4-不可变快照生成与哈希指纹算法" aria-label="Permalink to &quot;4. 不可变快照生成与哈希指纹算法&quot;">​</a></h2><p>当校验通过并发布时，控制面执行以下原子固化步骤：</p><ol><li><strong>版本号分配</strong>：查询 <code>MAX(version_number) + 1</code>，分配新 <code>version_id</code>（如 <code>ver_...</code>）；</li><li><strong>规范化 JSON 序列化 (Canonical JSON)</strong>： <ul><li>提取该租户名下所有 <code>status=&#39;active&#39;</code> 的 routes 和 policies；</li><li>按照 <code>route_id</code> 与 <code>policy_id</code> 进行字典升序排序；</li><li>去除所有无意义空格并序列化为严格 JSON 字符串；</li></ul></li><li><strong>计算确定性指纹</strong>： $$\\text{snapshotHash} = \\text{&quot;sha256:&quot;} + \\text{SHA256}(\\text{Canonical_JSON})$$</li><li><strong>原子落库</strong>： <ul><li>写入 <code>ap_config_version</code> 表；</li><li>将原先 <code>is_active=true</code> 的记录标记为 <code>false</code>；</li><li>触发版本变更事件通知（<code>LISTEN/NOTIFY</code>）。</li></ul></li></ol><hr><h2 id="_5-gateway-运行时缓存与刷新协议" tabindex="-1">5. Gateway 运行时缓存与刷新协议 <a class="header-anchor" href="#_5-gateway-运行时缓存与刷新协议" aria-label="Permalink to &quot;5. Gateway 运行时缓存与刷新协议&quot;">​</a></h2><p>Go Gateway 数据面采用 <strong>Push（事件触发） + Pull（定时巡检）</strong> 混合架构，确保配置刷新实时且零丢失：</p>',15)),(o(),d(n,null,{default:e(()=>[l(r,{id:"mermaid-302",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20autonumber%0A%20%20%20%20actor%20Admin%20as%20%E7%AE%A1%E7%90%86%E5%91%98%20(Web%20Console)%0A%20%20%20%20participant%20CP%20as%20%E6%8E%A7%E5%88%B6%E9%9D%A2%20(Control%20Plane)%0A%20%20%20%20participant%20PG%20as%20PostgreSQL%20(ap_config_version)%0A%20%20%20%20participant%20GW%20as%20Go%20Gateway%20(%E6%95%B0%E6%8D%AE%E9%9D%A2)%0A%0A%20%20%20%20Admin-%3E%3ECP%3A%20%E7%82%B9%E5%87%BB%E2%80%9C%E7%A1%AE%E8%AE%A4%E5%8F%91%E5%B8%83%E2%80%9D%0A%20%20%20%20CP-%3E%3ECP%3A%20%E9%9D%99%E6%80%81%E6%A0%A1%E9%AA%8C%E9%80%9A%E8%BF%87%2C%20%E8%AE%A1%E7%AE%97%20SHA-256%20%E5%BF%AB%E7%85%A7%E6%8C%87%E7%BA%B9%0A%20%20%20%20CP-%3E%3EPG%3A%20INSERT%20ap_config_version%20(active%3Dtrue)%0A%20%20%20%20CP-%3E%3EPG%3A%20NOTIFY%20config_update%2C%20'%7B%22tenant_id%22%3A%20%22ten_xxx%22%2C%20%22version%22%3A%203%7D'%0A%20%20%20%20%0A%20%20%20%20par%20%E5%AE%9E%E6%97%B6%20Push%20%E8%B7%AF%E5%BE%84%0A%20%20%20%20%20%20%20%20PG--%3E%3EGW%3A%20%E6%8E%A5%E6%94%B6%20LISTEN%20%E5%8F%98%E6%9B%B4%E9%80%9A%E7%9F%A5%0A%20%20%20%20%20%20%20%20GW-%3E%3EPG%3A%20%E6%8B%89%E5%8F%96%E6%96%B0%E5%BF%AB%E7%85%A7%20JSON%0A%20%20%20%20%20%20%20%20GW-%3E%3EGW%3A%20%E6%A0%A1%E9%AA%8C%20SHA-256%20%E6%8C%87%E7%BA%B9%E5%90%88%E6%B3%95%0A%20%20%20%20%20%20%20%20GW-%3E%3EGW%3A%20RCU%20%E5%8E%9F%E5%AD%90%E6%9B%BF%E6%8D%A2%E5%86%85%E5%AD%98%E8%B7%AF%E7%94%B1%E8%A1%A8%E6%8C%87%E9%92%88%0A%20%20%20%20and%20%E5%AE%9A%E6%97%B6%20Pull%20%E5%85%9C%E5%BA%95%E8%B7%AF%E5%BE%84%20(%E6%AF%8F%2030s)%0A%20%20%20%20%20%20%20%20GW-%3E%3EPG%3A%20SELECT%20version_number%2C%20snapshot_hash%20WHERE%20is_active%3Dtrue%0A%20%20%20%20%20%20%20%20opt%20%E5%8F%91%E7%8E%B0%E6%9C%AC%E5%9C%B0%E6%8C%87%E7%BA%B9%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%BA%93%E6%8C%87%E7%BA%B9%E4%B8%8D%E4%B8%80%E8%87%B4%0A%20%20%20%20%20%20%20%20%20%20%20%20GW-%3E%3EGW%3A%20%E8%A7%A6%E5%8F%91%E5%BC%BA%E5%88%B6%E7%83%AD%E5%8A%A0%E8%BD%BD%E5%88%B7%E6%96%B0%0A%20%20%20%20%20%20%20%20end%0A%20%20%20%20end%0A"})]),fallback:e(()=>[...t[1]||(t[1]=[i(" Loading... ",-1)])]),_:1})),t[4]||(t[4]=a('<hr><h2 id="_6-异常容灾与安全降级行为" tabindex="-1">6. 异常容灾与安全降级行为 <a class="header-anchor" href="#_6-异常容灾与安全降级行为" aria-label="Permalink to &quot;6. 异常容灾与安全降级行为&quot;">​</a></h2><table tabindex="0"><thead><tr><th>异常场景</th><th>网关运行时防御行为</th><th>安全保障</th></tr></thead><tbody><tr><td><strong>控制面完全宕机 / 网络中断</strong></td><td>Gateway 依靠<strong>当前内存中已有的配置快照及本地磁盘备份</strong>继续工作，绝不停摆。</td><td>保证已发布服务的持续可用性，控制面故障绝不影响数据面转发与计费。</td></tr><tr><td><strong>首次冷启动且数据库失联</strong></td><td>Gateway 启动时若完全无法获取任何快照，且本地无磁盘缓存，遵循 <strong>Fail-Closed（默认拒绝）</strong>：对所有请求返回 <code>503 Service Unavailable</code>。</td><td>严禁在无风控和无定价策略下放行任何外部调用，防止资金敞口泄露。</td></tr><tr><td><strong>快照哈希校验失败（篡改告警）</strong></td><td>若 Gateway 拉取到的快照反算哈希与声明的 <code>snapshotHash</code> 不一致，拒绝加载并保留现有配置，同时输出最高优先级安全告警日志。</td><td>防范传输链路劫持或恶意篡改。</td></tr></tbody></table><hr><h2 id="_7-秒级一键回滚-one-click-rollback" tabindex="-1">7. 秒级一键回滚 (One-Click Rollback) <a class="header-anchor" href="#_7-秒级一键回滚-one-click-rollback" aria-label="Permalink to &quot;7. 秒级一键回滚 (One-Click Rollback)&quot;">​</a></h2><p>若在线服务发布新规则后出现异常，管理员可在控制台执行一键秒级回滚：</p><ol><li>管理员指定历史目标版本（如从 <code>v3</code> 回滚至 <code>v1</code>）；</li><li>系统读取 <code>v1</code> 的 <code>snapshot_json</code>，生成新的自增版本记录 <code>v4</code>（<code>change_summary: &quot;Rollback to version v1&quot;</code>），但其负载与哈希严格等同于 <code>v1</code>；</li><li>将 <code>v4</code> 标记为 <code>active</code>；</li><li>Gateway 在数毫秒内完成原子指针切换，服务瞬间恢复到历史稳定状态。</li></ol>',7))])}const f=s(A,[["render",g]]);export{m as __pageData,f as default};
